<script setup>import{useForm}from'@inertiajs/vue3';import AdminLayout from'../../../Layouts/AdminLayout.vue';const props=defineProps({order:Object}),form=useForm({status:props.order.status,payment_status:props.order.payment_status,note:''});</script><template><AdminLayout><p class="section-kicker">{{order.order_number}}</p><h1 class="section-title">Order details</h1><div class="mt-6 grid gap-5 lg:grid-cols-[1fr_360px]"><div class="grid gap-5"><section class="card p-5"><h2 class="font-black">Items</h2><div v-for="i in order.items" :key="i.id" class="flex justify-between border-b py-3"><span>{{i.product_name}} × {{i.quantity}}</span><b>TZS {{Number(i.line_total).toLocaleString()}}</b></div></section><section class="card p-5"><h2 class="font-black">History</h2><div class="mt-3 space-y-3"><div v-for="h in order.status_history" :key="h.id" class="border-l-2 border-prinx-500 pl-3"><p class="font-bold capitalize">{{h.status}} · {{h.payment_status}}</p><p class="text-sm text-slate-500">{{h.note}}</p></div></div></section></div><form class="card h-fit p-5" @submit.prevent="form.patch(`/admin/orders/${order.id}`)"><h2 class="font-black">Update order</h2><div class="mt-4 grid gap-4"><select v-model="form.status" class="input"><option v-for="s in ['pending','confirmed','processing','ready','shipped','completed','cancelled']" :key="s" :value="s">{{s}}</option></select><select v-model="form.payment_status" class="input"><option v-for="s in ['pending','paid','failed','refunded']" :key="s" :value="s">{{s}}</option></select><textarea v-model="form.note" class="input" placeholder="Internal note"></textarea><button class="btn-primary">Update</button></div></form></div></AdminLayout></template>
